import re

# Let me carefully look at the table row structure again
text = open('/app/resources/treasury_bulletin_1941_05_page_32.txt').read()

# Find year marker positions more carefully
all_rows = re.split(r'<tr>', text)

# Find where each year section starts and ends
year_sections = {}
current_year = None

for i, row in enumerate(all_rows):
    cells = re.findall(r'<td>(.*?)</td>', row)
    if cells and cells[0].isdigit() and len(cells[0]) == 4:
        current_year = cells[0]
        year_sections[current_year] = {'start': i, 'entries': []}
    elif current_year and 'Nat. Defense Series' in row:
        # Check if it's in first callable section (first column)
        if 'Nat. Defense Series' in cells[0]:
            year_sections[current_year]['entries'].append({
                'row': i,
                'description': cells[0],
                'fixed': cells[1] if len(cells) > 1 else '',
                'callable': cells[2] if len(cells) > 2 else ''
            })

print("Year sections:")
for year, data in year_sections.items():
    print(f"\nYear {year}:")
    for entry in data['entries']:
        print(f"  Row {entry['row']}: {entry['description']}")
        print(f"    Fixed: {entry['fixed']}, Callable: {entry['callable']}")
EOF
